//! The Amazon Web Services Secrets Manager secret RDS MANAGES for a resource's master
//! user password, and the minting a request that turns that management on depends on.
//!
//! `ManageMasterUserPassword` has RDS "generate and manage the master user password with
//! Amazon Web Services Secrets Manager" and report the secret it owns as the resource's
//! `MasterUserSecret` (`SecretArn`, `SecretStatus`, `KmsKeyId`). So a request that turns
//! it on makes RDS do three things, and all three happen here:
//!
//! 1. GENERATE the password. It is generated by Secrets Manager's own generator
//!    (`GetRandomPassword`), excluding the characters `MasterUserPassword` forbids and as
//!    long as the engine the password belongs to allows
//!    ([`super::master_user_password_len`]), so the generated value is one that member
//!    would itself accept.
//! 2. STORE it in a secret Secrets Manager holds: `CreateSecret` under the name RDS gives
//!    a secret of its own ([`cluster_master_user_secret_name`] and its siblings), whose
//!    value is the `{"username", "password"}` document an RDS-managed secret holds. The
//!    secret is a real secret of the emulated Secrets Manager, so `GetSecretValue` on the
//!    ARN this reports answers with those credentials.
//! 3. REPORT it. The stored [`ManagedMasterSecret`] is what the resource projects, with
//!    the ARN Secrets Manager allocated, the identity of the KMS key the secret is
//!    encrypted under, and the status the clock owes.
//!
//! Secrets Manager and KMS are reached the way the rest of this emulator reaches another
//! service: the AWS SDK driven over the emulator's own in-process transport, through the
//! operation callback ([`smithy_server_runtime::OperationContext::callback`]), so no
//! socket is opened and no request leaves the process.
//!
//! The password itself is never stored on this service's records and never reported: it
//! goes into the secret, and what a caller gets back is the secret's ARN. A create that
//! also has to verify a login on the instance's own engine endpoint digests it in the
//! same call it was generated in ([`MintedMasterSecret::password`]) and keeps only the
//! digest, exactly as a request that carried its own `MasterUserPassword` does.

use super::*;

/// `MasterUserSecret$SecretStatus` while the secret is being created: "`creating` - The
/// secret is being created."
pub const MASTER_USER_SECRET_STATUS_CREATING: &str = "creating";

/// `MasterUserSecret$SecretStatus` once it can be used: "`active` - The secret is
/// available for normal use and rotation."
pub const MASTER_USER_SECRET_STATUS_ACTIVE: &str = "active";

/// `MasterUserSecret$SecretStatus` while a rotation is staking a new password:
/// "`rotating` - The secret is being rotated."
pub const MASTER_USER_SECRET_STATUS_ROTATING: &str = "rotating";

/// The secret RDS manages for one resource's master user password, as that resource
/// stores it.
///
/// The ARN and the KMS key are the identity Secrets Manager and KMS gave the secret, so
/// they are stored as those services answered them. The STATUS is not stored: it is the
/// one the clock owes, derived from when this secret settles ([`Self::status`]), so a
/// caller reading straight after the call that minted it still sees `creating` and no
/// read moves it.
#[derive(Debug, Clone)]
pub struct ManagedMasterSecret {
    /// `MasterUserSecret$SecretArn`: the ARN Secrets Manager allocated for the secret.
    pub secret_arn: String,
    /// `MasterUserSecret$KmsKeyId`: "The Amazon Web Services KMS key identifier that is
    /// used to encrypt the secret."
    pub kms_key_id: String,
    /// What the secret reports until [`Self::settles_at`]: `creating` for one just
    /// minted, `rotating` for one a rotation re-staked.
    transient_status: &'static str,
    /// When the secret reaches [`MASTER_USER_SECRET_STATUS_ACTIVE`].
    settles_at: Instant,
}

impl ManagedMasterSecret {
    /// The record for a secret this call has just created: it reports `creating` and
    /// reaches `active` on its own, [`STATUS_TRANSITION_DELAY`] from now. Nothing sleeps
    /// — the due instant is what is stored.
    pub fn minted(secret_arn: String, kms_key_id: String) -> Self {
        Self {
            secret_arn,
            kms_key_id,
            transient_status: MASTER_USER_SECRET_STATUS_CREATING,
            settles_at: Instant::now() + STATUS_TRANSITION_DELAY,
        }
    }

    /// Record that a rotation is under way: the secret reports `rotating` until it
    /// settles, the same span later.
    pub fn rotating(&mut self) {
        self.transient_status = MASTER_USER_SECRET_STATUS_ROTATING;
        self.settles_at = Instant::now() + STATUS_TRANSITION_DELAY;
    }

    /// `MasterUserSecret$SecretStatus` as of now.
    pub fn status(&self) -> &'static str {
        if Instant::now() >= self.settles_at {
            MASTER_USER_SECRET_STATUS_ACTIVE
        } else {
            self.transient_status
        }
    }

    /// Project the stored secret onto the modelled `MasterUserSecret` shape — the one
    /// way a resource reports its managed secret.
    pub fn to_wire(&self) -> MasterUserSecret {
        MasterUserSecret {
            secret_arn: Some(self.secret_arn.clone()),
            secret_status: Some(self.status().to_string()),
            kms_key_id: Some(self.kms_key_id.clone()),
        }
    }
}

impl serde::Serialize for ManagedMasterSecret {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        #[derive(serde::Serialize)]
        struct Wire<'a> {
            secret_arn: &'a str,
            kms_key_id: &'a str,
            transient_status: &'a str,
            #[serde(with = "crate::state::serde_instant_deadline")]
            settles_at: Instant,
        }
        Wire {
            secret_arn: &self.secret_arn,
            kms_key_id: &self.kms_key_id,
            transient_status: self.transient_status,
            settles_at: self.settles_at,
        }
        .serialize(serializer)
    }
}

impl<'de> serde::Deserialize<'de> for ManagedMasterSecret {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        #[derive(serde::Deserialize)]
        struct Wire {
            secret_arn: String,
            kms_key_id: String,
            transient_status: String,
            #[serde(with = "crate::state::serde_instant_deadline")]
            settles_at: Instant,
        }
        let wire = Wire::deserialize(deserializer)?;
        let transient_status = match wire.transient_status.as_str() {
            MASTER_USER_SECRET_STATUS_ROTATING => MASTER_USER_SECRET_STATUS_ROTATING,
            _ => MASTER_USER_SECRET_STATUS_CREATING,
        };
        Ok(Self {
            secret_arn: wire.secret_arn,
            kms_key_id: wire.kms_key_id,
            transient_status,
            settles_at: wire.settles_at,
        })
    }
}

/// The prefix every secret RDS MANAGES is named under: the service's own id and the
/// character AWS reserves for a secret an AWS service owns.
///
/// A secret in this form is not a caller's to create — the mark is not one of the
/// characters a secret name may carry ("ASCII letters, numbers, and the following
/// characters: /_+=.@-", `CreateSecretRequest$Name`), so a caller's `CreateSecret` cannot
/// name one at all — which is what makes the name itself say the secret is RDS's. It is
/// accepted from the service whose own principal is making the create
/// ([`::service_com_amazonaws_secretsmanager_secretsmanager::state::service_owned`]).
pub const MANAGED_SECRET_NAME_PREFIX: &str = "rds!";

/// The name of the secret RDS manages for a DB CLUSTER's master user password.
///
/// It carries the cluster's immutable `DbClusterResourceId` rather than its identifier,
/// which can be renamed, so the secret of a cluster is still the secret of that cluster
/// afterwards, under the reserved prefix every RDS-managed secret carries
/// ([`MANAGED_SECRET_NAME_PREFIX`]) and then the kind of resource it belongs to.
pub fn cluster_master_user_secret_name(resource_id: &str) -> String {
    format!("{MANAGED_SECRET_NAME_PREFIX}cluster-{resource_id}")
}

/// The name of the secret RDS manages for a DB INSTANCE's master user password, carrying
/// the instance's immutable `DbiResourceId`; see [`cluster_master_user_secret_name`].
pub fn instance_master_user_secret_name(resource_id: &str) -> String {
    format!("{MANAGED_SECRET_NAME_PREFIX}db-{resource_id}")
}

/// The tag AWS applies to the secret RDS manages for a DB INSTANCE's master user
/// password: a fixed key whose value is that instance's `DBInstanceArn`, which is how a
/// client answers "which database do these credentials belong to?" from the secret alone,
/// and what a tag-scoped policy written for such a secret matches on.
pub const PRIMARY_DB_INSTANCE_ARN_TAG: &str = "aws:rds:primaryDBInstanceArn";

/// The same tag for the secret of a DB CLUSTER's master user password, whose value is the
/// cluster's `DBClusterArn`.
pub const PRIMARY_DB_CLUSTER_ARN_TAG: &str = "aws:rds:primaryDBClusterArn";

/// The resource a managed secret belongs to, as the secret itself reports it: the
/// AWS-applied tag naming that resource's ARN.
#[derive(Debug, Clone, Copy)]
pub struct ManagedSecretOwner<'a> {
    /// The tag key for the kind of resource that owns the secret.
    pub tag_key: &'static str,
    /// That resource's ARN, which is the tag's value.
    pub arn: &'a str,
}

impl<'a> ManagedSecretOwner<'a> {
    /// The secret of the DB INSTANCE `arn` names — also the owner of the secret of a
    /// TENANT DATABASE of that instance, whose master user is a user of that instance.
    #[must_use]
    pub fn db_instance(arn: &'a str) -> Self {
        Self {
            tag_key: PRIMARY_DB_INSTANCE_ARN_TAG,
            arn,
        }
    }

    /// The secret of the DB CLUSTER `arn` names.
    #[must_use]
    pub fn db_cluster(arn: &'a str) -> Self {
        Self {
            tag_key: PRIMARY_DB_CLUSTER_ARN_TAG,
            arn,
        }
    }
}

/// What a request that turns management on asks for: the secret to create, the master
/// user it holds the password of, the engine whose password rules the generated value
/// must satisfy, and the KMS key to encrypt it under.
#[derive(Debug)]
pub struct MasterSecretRequest<'a> {
    /// The secret's name, from one of the `*_master_user_secret_name` helpers.
    pub name: &'a str,
    /// `MasterUsername`, the user whose password the secret holds.
    pub username: Option<&'a str>,
    /// The resource's engine, which publishes how long the password may be.
    pub engine: &'a str,
    /// The resource whose master user password this secret holds, which the secret reports
    /// through the AWS-applied tag naming its ARN.
    pub owner: ManagedSecretOwner<'a>,
    /// `MasterUserSecretKmsKeyId`: "The Amazon Web Services KMS key identifier to encrypt
    /// a secret that is automatically generated and managed in Amazon Web Services
    /// Secrets Manager … If you don't specify MasterUserSecretKmsKeyId, then the
    /// aws/secretsmanager KMS key is used to encrypt the secret."
    pub kms_key_id: Option<&'a str>,
}

/// A minted managed secret: the record the resource stores, and the password that went
/// into it — which only the call that minted it ever sees.
pub struct MintedMasterSecret {
    pub secret: ManagedMasterSecret,
    /// The generated password, for a resource whose own engine endpoint verifies logins
    /// against it. Never stored as itself and never reported.
    pub password: String,
}

/// The password is left OUT of the formatted form: it is a live credential, and a derived
/// `Debug` is how one reaches a log.
impl std::fmt::Debug for MintedMasterSecret {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("MintedMasterSecret")
            .field("secret", &self.secret)
            .finish_non_exhaustive()
    }
}

/// Mint the managed master user secret `asked` describes: generate the password, store it
/// in a new Secrets Manager secret, and report the secret the resource will carry.
///
/// `Err` carries the sentence to report the failure with. Every failure here is a failure
/// of this EMULATOR to do what RDS does — Secrets Manager not mounted beside this
/// service, or a store that would not take the secret — never anything the request
/// carried: the values it carries are checked by the handler before this is called.
pub async fn mint_master_user_secret<Eng: Send + Sync + 'static>(
    engine: &Eng,
    ctx: &smithy_server_runtime::OperationContext<'_>,
    region: &str,
    asked: &MasterSecretRequest<'_>,
) -> Result<MintedMasterSecret, String> {
    let secrets = secrets_manager_client(ctx, region).ok_or_else(unaskable_region)?;
    let password = generated_password(&secrets, asked.engine).await?;
    // The secret is one RDS OWNS, so the create is made as RDS's OWN service principal
    // acting for the resource the secret belongs to ([`ServicePrincipalCall`]): that is
    // what lets it be named under the reserved prefix no caller can mint, be reported with
    // `OwningService`, and carry the AWS-applied tag naming its resource. A call that
    // cannot be made that way cannot create that secret AT ALL — the reserved name and the
    // AWS-applied tag are refused for anyone else — so it is reported as this emulator
    // failing to create the secret rather than quietly creating an ordinary one of the
    // account under a name a caller could mint.
    let acting = ServicePrincipalCall::begin(engine, ctx, asked.owner.arn)
        .ok_or_else(|| unactable_principal("created", asked.owner.arn))?;
    let secrets = acting.secrets_manager_client(ctx, region)?;
    let created = secrets
        .create_secret()
        .name(asked.name)
        .client_request_token(fresh_version_token())
        .secret_string(credentials_document(asked.username, &password))
        .set_kms_key_id(asked.kms_key_id.map(str::to_string))
        .tags(
            ::aws_sdk_secretsmanager::types::Tag::builder()
                .key(asked.owner.tag_key)
                .value(asked.owner.arn)
                .build(),
        )
        .send()
        .await
        .map_err(|error| {
            format!(
                "the master user secret could not be created in Amazon Web Services Secrets \
                 Manager: {}",
                ::aws_smithy_types::error::display::DisplayErrorContext(&error)
            )
        })?;
    let Some(secret_arn) = created.arn().map(str::to_string) else {
        return Err(
            "Amazon Web Services Secrets Manager created the master user secret without an ARN"
                .to_string(),
        );
    };
    let kms_key_id = encrypting_key_id(ctx, region, asked.kms_key_id).await;
    Ok(MintedMasterSecret {
        secret: ManagedMasterSecret::minted(secret_arn, kms_key_id),
        password,
    })
}

/// Rotate a managed secret: generate another password and stake it as the secret's
/// current value, so the credentials the secret holds are the new ones from now on.
///
/// The write is made as RDS's OWN service principal acting for the resource the secret
/// belongs to ([`ServicePrincipalCall`]), exactly as the create is: the secret is one RDS
/// owns, and such a secret is only written by the service that manages it — a caller's own
/// `PutSecretValue` on it is refused.
///
/// Returns the new password, for the same reason [`MintedMasterSecret::password`] carries
/// one. `Err` carries the sentence to report the failure with, as in
/// [`mint_master_user_secret`].
pub async fn rotate_master_user_secret<Eng: Send + Sync + 'static>(
    engine: &Eng,
    ctx: &smithy_server_runtime::OperationContext<'_>,
    region: &str,
    owner_arn: &str,
    secret_arn: &str,
    username: Option<&str>,
    db_engine: &str,
) -> Result<String, String> {
    let secrets = secrets_manager_client(ctx, region).ok_or_else(unaskable_region)?;
    let password = generated_password(&secrets, db_engine).await?;
    let acting = ServicePrincipalCall::begin(engine, ctx, owner_arn)
        .ok_or_else(|| unactable_principal("rotated", owner_arn))?;
    acting
        .secrets_manager_client(ctx, region)?
        .put_secret_value()
        .secret_id(secret_arn)
        .client_request_token(fresh_version_token())
        .secret_string(credentials_document(username, &password))
        .send()
        .await
        .map_err(|error| {
            format!(
                "the master user secret could not be rotated in Amazon Web Services Secrets \
                 Manager: {}",
                ::aws_smithy_types::error::display::DisplayErrorContext(&error)
            )
        })?;
    Ok(password)
}

/// Release a managed secret: RDS "deletes the secret" when a request turns management of
/// the master user password off, so the credentials it held can no longer be read.
///
/// The delete goes through Secrets Manager's own `DeleteSecret`, which is what owns the
/// secret's lifecycle — so the secret leaves service exactly as any other deleted secret
/// does, and nothing of this service's own pretends it is gone. It is made as RDS's own
/// service principal acting for the resource the secret belongs to, for the same reason the
/// create and the rotation are: the lifecycle of a secret RDS owns is RDS's, and a caller's
/// own `DeleteSecret` on it is refused. `Err` carries the sentence to report the failure
/// with, as in [`mint_master_user_secret`].
pub async fn release_master_user_secret<Eng: Send + Sync + 'static>(
    engine: &Eng,
    ctx: &smithy_server_runtime::OperationContext<'_>,
    region: &str,
    owner_arn: &str,
    secret_arn: &str,
) -> Result<(), String> {
    let acting = ServicePrincipalCall::begin(engine, ctx, owner_arn)
        .ok_or_else(|| unactable_principal("deleted", owner_arn))?;
    acting
        .secrets_manager_client(ctx, region)?
        .delete_secret()
        .secret_id(secret_arn)
        // The secret goes with the resource rather than into a recovery window: it is RDS's
        // own, so nobody but RDS could take it back out of one, and its NAME is the
        // resource's ([`instance_master_user_secret_name`] and its siblings) — so a request
        // that turns the management back on for that same resource has to be able to mint
        // it again, which a secret still occupying the name would refuse.
        .force_delete_without_recovery(true)
        .send()
        .await
        .map_err(|error| {
            format!(
                "the master user secret could not be deleted in Amazon Web Services Secrets \
                 Manager: {}",
                ::aws_smithy_types::error::display::DisplayErrorContext(&error)
            )
        })?;
    Ok(())
}

/// Delete a managed secret this call minted for a resource it then could not store, so
/// nothing is left behind that no resource reports.
///
/// Best effort by design: the answer to the caller is the refusal that made the secret an
/// orphan, so a Secrets Manager call that fails here cannot change it — it is recorded and
/// the refusal stands.
pub async fn release_orphaned_master_user_secret<Eng: Send + Sync + 'static>(
    engine: &Eng,
    ctx: &smithy_server_runtime::OperationContext<'_>,
    region: &str,
    owner_arn: &str,
    secret_arn: &str,
) {
    if let Err(message) = release_master_user_secret(engine, ctx, region, owner_arn, secret_arn).await
    {
        ::tracing::debug!(
            secret = secret_arn,
            %message,
            "the master user secret minted for a resource this call could not store was not \
             deleted"
        );
    }
}

/// The password RDS generates for a managed secret, from Secrets Manager's own generator.
///
/// It is generated for the engine the password belongs to: as long as that engine's
/// `MasterUserPassword` allows ([`master_user_password_len`]) and without the characters
/// that member forbids, so the generated value satisfies the same rules a password a
/// caller supplied is held to ([`check_master_user_password`]).
async fn generated_password(
    secrets: &::aws_sdk_secretsmanager::Client,
    engine: &str,
) -> Result<String, String> {
    let length = i64::try_from(*master_user_password_len(engine).end()).unwrap_or(i64::MAX);
    let generated = secrets
        .get_random_password()
        .password_length(length)
        .exclude_characters(MASTER_USER_PASSWORD_EXCLUDED_CHARACTERS)
        .include_space(false)
        .send()
        .await
        .map_err(|error| {
            format!(
                "the master user password could not be generated in Amazon Web Services Secrets \
                 Manager: {}",
                ::aws_smithy_types::error::display::DisplayErrorContext(&error)
            )
        })?;
    generated
        .random_password()
        .map(str::to_string)
        .ok_or_else(|| {
            "Amazon Web Services Secrets Manager generated no master user password".to_string()
        })
}

/// The characters a generated master user password leaves out: the ones
/// `MasterUserPassword` documents it "can't contain" — "/", "\"" and the "@" symbol —
/// which [`check_master_user_password`] refuses a supplied password for.
const MASTER_USER_PASSWORD_EXCLUDED_CHARACTERS: &str = "/\"@";

/// The value an RDS-managed secret holds: the master user's name and the password RDS
/// generated for it, as the JSON document a client reads the credentials out of.
fn credentials_document(username: Option<&str>, password: &str) -> String {
    let mut document = ::serde_json::Map::new();
    if let Some(username) = username {
        document.insert(
            "username".to_string(),
            ::serde_json::Value::String(username.to_string()),
        );
    }
    document.insert(
        "password".to_string(),
        ::serde_json::Value::String(password.to_string()),
    );
    ::serde_json::Value::Object(document).to_string()
}

/// A version id for the secret version this call stakes.
///
/// `ClientRequestToken` becomes the version's id and "if you generate a raw HTTP request
/// to the Secrets Manager service endpoint, then you must generate a ClientRequestToken
/// and include it in the request" — which is the position this service is in, since it is
/// RDS that creates and rotates the secret. It is drawn from the operating system's own
/// entropy, so two calls never stake the same version.
fn fresh_version_token() -> String {
    let mut bytes = [0_u8; 16];
    if ::getrandom::fill(&mut bytes).is_err() {
        // Entropy the OS would not hand over: the token still has to be unique, and the
        // clock's reading is what this process can still tell two calls apart by.
        bytes = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .map(|since| since.as_nanos())
            .unwrap_or_default()
            .to_le_bytes();
    }
    ::hex::encode(bytes)
}

/// The `KmsKeyId` to report for a managed secret: the ARN of the key it is encrypted
/// under.
///
/// A secret is encrypted under the key the request named, or — when it named none — under
/// the Amazon Web Services managed key `aws/secretsmanager`, which is what
/// `MasterUserSecretKmsKeyId` documents as the default. Either way the key is resolved
/// through [`resolve_key_arn`], so what is reported is the key's OWN identity rather than an
/// alias that may later point elsewhere.
async fn encrypting_key_id(
    ctx: &smithy_server_runtime::OperationContext<'_>,
    region: &str,
    requested: Option<&str>,
) -> String {
    resolve_key_arn(
        ctx,
        region,
        requested.unwrap_or(SECRETS_MANAGER_DEFAULT_KEY_ALIAS),
    )
    .await
}

/// The ARN of the KMS key `named` resolves to, for a member that reports the key something
/// of this service is encrypted under.
///
/// `DescribeKey` "associates the alias with an Amazon Web Services managed key and returns
/// its KeyId and Arn" for a predefined AWS alias, so an alias is resolved to the key's own
/// identity rather than reported as given.
///
/// A lookup KMS does not answer — a deployment with no KMS mounted beside this service, a
/// fault, a key this account does not hold — says nothing about the identifier, so `named`
/// stands: the resource is still encrypted under that key, and that is what names it. None
/// of the operations that take a key identifier models a KMS fault for a key that cannot be
/// resolved, which is why this answers a `String` rather than a `Result`.
///
/// `pub(super)` because every member of this service that reports an encryption key — the
/// managed secret's above and a cluster's or instance's storage key
/// ([`super::storage_encryption_key`]) — resolves it this one way, so no two of them state
/// the fallback differently.
pub(super) async fn resolve_key_arn(
    ctx: &smithy_server_runtime::OperationContext<'_>,
    region: &str,
    named: &str,
) -> String {
    let Some(kms) = kms_client(ctx, region) else {
        // The signing scope names no Region this emulator can ask KMS in, so nothing was
        // learned about the key and the identifier in hand stands.
        return named.to_string();
    };
    match kms.describe_key().key_id(named).send().await {
        Ok(described) => described
            .key_metadata()
            .and_then(|metadata| metadata.arn())
            .map(str::to_string)
            .unwrap_or_else(|| named.to_string()),
        Err(error) => {
            ::tracing::debug!(
                kms_key = named,
                error = %::aws_smithy_types::error::display::DisplayErrorContext(&error),
                "KMS did not resolve the key this service reports something as encrypted \
                 under; reporting the identifier in hand"
            );
            named.to_string()
        }
    }
}

/// The Amazon Web Services managed key a secret is encrypted under when the request names
/// none: "If you don't specify MasterUserSecretKmsKeyId, then the aws/secretsmanager KMS
/// key is used to encrypt the secret" (`MasterUserSecretKmsKeyId`), named by the alias
/// AWS publishes for it.
const SECRETS_MANAGER_DEFAULT_KEY_ALIAS: &str = "alias/aws/secretsmanager";

/// The sentence a managed-secret call reports when the request's signing scope names no
/// Region this emulator can ask a peer service in ([`secrets_manager_client`]): a failure of
/// this emulator to reach the service that owns the secret, like the others here.
fn unaskable_region() -> String {
    unaskable_region_message()
}

/// The same sentence, for the sibling module that builds a client of its own
/// ([`super::ServicePrincipalCall::secrets_manager_client`]).
pub(super) fn unaskable_region_message() -> String {
    "the master user secret could not be reached in Amazon Web Services Secrets Manager: the \
     request's signing scope names no Amazon Web Services Region"
        .to_string()
}

/// The sentence reported when this emulator could not make the call AS the RDS service
/// principal acting for `owner` ([`ServicePrincipalCall::begin`]).
///
/// Such a secret is RDS's own — its name and its tags are not a caller's to write, and
